def divides(d, n):
    return n % d == 0


m = int(input())
for i in range(m):
    n = int(input())
    count = 0
    for d in range(1, n + 1):
        if d * d <= n and divides(d, n):
            print(f"{n} = {d} * {n // d}")
            if d * d == n:
                count = count + 1
            else:
                count = count + 2
    if divides(2, n):
        parity = "even"
    else:
        parity = "odd"
    print(f"{n}: {count} divisors, {parity}")

def digit_sum(n):
    total = 0
    for k in range(12):
        total = total + (n // 10 ** k) % 10
    return total


def alternating_sum(n):
    total = 0
    for k in range(12):
        digit = (n // 10 ** k) % 10
        if k % 2 == 0:
            total = total + digit
        else:
            total = total - digit
    return total


m = int(input())
for i in range(m):
    n = int(input())
    two = n % 100
    s = digit_sum(n)
    a = alternating_sum(n)
    print(f"{n}: last two digits {two}, digit sum {s}, alternating sum {a}")
    print(f"by 4: {two % 4 == 0}, by 3: {s % 3 == 0}, by 9: {s % 9 == 0}, by 11: {a % 11 == 0}")
